window.kbPageData["views/entry/k-c7fdbb32c610a4e7"] = {"key":"entry/k-c7fdbb32c610a4e7","state":{"route":"entry/k-c7fdbb32c610a4e7"},"node":{"id":"k-c7fdbb32c610a4e7","mode":"k","title":"阿基米德原理与漂浮平衡","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 副省级 行测#75"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"液体对物体的浮力等于物体排开液体的重力，即液体密度、排液体积和重力加速度三者的乘积。物体仅受重力和浮力并保持漂浮时，浮力等于物体重力。","review":{"definition":"液体对物体的浮力等于物体排开液体的重力，即液体密度、排液体积和重力加速度三者的乘积。物体仅受重力和浮力并保持漂浮时，浮力等于物体重力。","explanation":"同一个圆锥体在两种液体中均漂浮，重力相同，浮力也相同。因此排液体积与液体密度成反比，密度为1.5的液体B中的排液体积是密度为1的液体A中的三分之二。A中浸没部分是高为0.9x的相似圆锥，占总体积的72.9%，所以B中浸没部分占48.6%。尖部朝上时，露出的圆锥体积占51.4%，略大于0.8³＝0.512，故露出高度超过0.8x，对应A项。","references":[],"evidence":"两种放置方式所受浮力相等","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 副省级 行测#75":{"paper":"国考 2023 副省级 行测","n":75,"mod":"数量关系","src":["503793642e845de9795f.pdf",13],"asrc":["ecade1ff5af69283232e.pdf",22],"card":"29ff74f14f6c672d4875465e","links":[{"id":"k-c7fdbb32c610a4e7","role":"解题依据","why":"漂浮时浮力等于物体重力，且浮力等于所排开液体的重力，据此可换算两种液体中的排液体积。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-c7fdbb32c610a4e7":[["国考 2023 副省级 行测#75"]]}};
